    "NCE2-6": {
      id: "NCE2-6", book: "NCE2", n: 6, title: "Percy Buttons", titleZh: "珀西·巴顿斯",
      audio: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/06PercyButtons.mp3", lrc: "https://raw.githubusercontent.com/sufangmu/NCE/refs/heads/main/NCE2/06PercyButtons.lrc", introLines: 1,
      words: [
        { en: "beggar", ipa: "/ˈbɛɡɚ/", pos: "名词", zh: "乞丐" },
        { en: "pocket", ipa: "/ˈpɑkɪt/", pos: "名词", zh: "口袋" },
        { en: "neighbour", ipa: "/ˈnebɚ/", pos: "名词", zh: "邻居" },
        { en: "meal", ipa: "/mil/", pos: "名词", zh: "一餐" },
      ],
      text: [
        { en: "I have just moved to a house in Bridge Street.", zh: "我刚刚搬进了大桥街的一所房子。" },
        { en: "Yesterday a beggar knocked at my door.", zh: "昨天一个乞丐来敲我的门，" },
        { en: "He asked me for a meal and a glass of beer.", zh: "问我要一顿饭和一杯啤酒。" },
        { en: "In return for this,", zh: "作为回报，" },
        { en: "the beggar stood on his head and sang songs.", zh: "那乞丐头顶地倒立起来，嘴里还唱着歌。" },
        { en: "I gave him a meal.", zh: "我给了他一顿饭。" },
        { en: "He ate the food and drank the beer.", zh: "他把食物吃完，又喝了酒。" },
        { en: "Then he put a piece of cheese in his pocket and went away.", zh: "然后把一块乳酪装进衣袋里走了。" },
        { en: "Later a neighbour told me about him.", zh: "后来，一位邻居告诉了我他的情况。" },
        { en: "Everybody knows him.", zh: "大家都认识他，" },
        { en: "His name is Percy Buttons.", zh: "他叫珀西·巴顿斯。" },
        { en: "He calls at every house in the street once a month", zh: "他每月对这条街上的每户人家光顾一次，" },
        { en: "and always asks for a meal and a glass of beer.", zh: "总是请求给他一顿饭和一杯啤酒。" },
      ],
      expressions: [
        { en: "move to sw.", zh: "搬到某地", examples: ["I have just moved to a house in Bridge Street."] },
        { en: "knock at the door", zh: "敲门", examples: ["A beggar knocked at my door."] },
        { en: "ask sb. for sth.", zh: "向某人要某物", examples: ["He asked me for a meal."] },
        { en: "stand on one's head", zh: "倒立", examples: ["The beggar stood on his head."] },
        { en: "in return for this", zh: "作为回报", examples: ["In return for this, the beggar stood on his head."] },
        { en: "call at", zh: "拜访（某地）", examples: ["He calls at every house once a month."] },
      ],
    },

