      text: [
        { en: "We have an old musical instrument.", zh: "我们有一件古老的乐器。" },
        { en: "It is called a clavichord.", zh: "它叫古钢琴。" },
        { en: "It was made in Germany in 1681.", zh: "它是1681年德国制造的。" },
        { en: "Our clavichord is kept in the living room.", zh: "我们的这架古钢琴存放在起居室里。" },
        { en: "It has belonged to our family for a long time.", zh: "我们家有这件乐器已经很久了。" },
        { en: "The instrument was bought by my grandfather many years ago.", zh: "这件乐器是许多年以前我祖父买的。" },
        { en: "Recently it was damaged by a visitor.", zh: "最近，它被一位客人弄坏了。" },
        { en: "She tried to play jazz on it!", zh: "她想用它弹奏爵士乐！" },
        { en: "She struck the keys too hard and two of the strings were broken.", zh: "她在击琴键时用力过猛，把两根弦弄断了。" },
        { en: "My father was shocked.", zh: "我父亲大为吃惊。" },
        { en: "Now we are not allowed to touch it.", zh: "现在他不允许我们再碰它。" },
        { en: "It is being repaired by a friend of my father's.", zh: "父亲的一个朋友正在修理这件乐器。" },
      ],
      expressions: [
        { en: "musical instrument", zh: "乐器", examples: ["We have an old musical instrument."] },
        { en: "be allowed to do sth.", zh: "被允许做某事", examples: ["Now we are not allowed to touch it."] },
        { en: "allow sb. to do sth.", zh: "允许某人做某事", examples: ["He doesn't allow us to touch it."] },
        { en: "be made in", zh: "在……制造", examples: ["It was made in Germany in 1681."] },
        { en: "belong to", zh: "属于", examples: ["It has belonged to our family for a long time."] },
      ],
